import {classifyPrediction,summarize,cropRegion,loadRemoteModel,loadLocalModel,loadBundledModel} from './model.js';
import {validateRegions,regionWarnings,sameRegions} from './regions.js';
import {preparePhoto} from './image-input.js';
import {inspectCanvas,QUALITY_VERSION} from './quality.js';
import {fingerprintFile,normalizeHistory,upsertEvaluation,exportEvaluationCSV} from './evaluation.js';
const $=id=>document.getElementById(id), ids=['A1','A2','A3','A4'];
const defaults=()=>ids.map((id,i)=>({id,x:.105+i*.205,y:.24,w:.175,h:.55}));
const fixture=[.98,.04,.33,.94].map(p=>[{className:'빈자리',probability:p},{className:'사용 중',probability:1-p}]);
let rois=defaults(),predictions=fixture,results=[],mode='demo',model=null,emptyClass='빈자리',occupiedClass='사용 중',modelTab='bundled',busy=false,editing=false,selected=0,frameId='demo',revision=0,activePhoto=null,lastRun=null,expanded=new Set(),history=[];
let imageHash=null,analyzedAt=null,qualityChecks=[],cancelRequested=false,analysisActive=false,analysisDuration=null;
const PREPROCESSING={version:'roi-rgb224-v1',resize:'full rectangle to224x224',normalization:'TM RGB/127-1',quality:QUALITY_VERSION};
function newFrameId(){if(globalThis.crypto?.randomUUID)return globalThis.crypto.randomUUID();const bytes=new Uint8Array(16);globalThis.crypto.getRandomValues(bytes);return Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');}
const labels={empty:'빈자리',occupied:'사용 중',uncertain:'확인 필요',pending:'분석 대기'};
try{history=normalizeHistory(localStorage.getItem('parking-four-history')||'[]');}catch{}
function toast(message,error=false){const modal=document.querySelector('dialog[open]');if(modal){let note=modal.querySelector('.dialog-feedback');if(!note){note=document.createElement('p');note.className='dialog-feedback form-message';note.setAttribute('role','status');modal.append(note);}note.textContent=message;note.className='dialog-feedback form-message'+(error?' error':'');return;}$('toast').textContent=message;$('toast').className=error?'error':'';$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,5000);}
function open(id){$(id).querySelector('.dialog-feedback')?.remove();$(id).showModal();}
function setBusy(value){busy=value;for(const id of ['analyze-btn','load-model','disconnect-model','save-mapping','upload-btn','image-file','sample-btn','save-rois','reset-rois','roi-file','threshold','start-model-btn','save-profile','delete-profile','profile-select','roi-confirmed','real-example-btn'])if($(id))$(id).disabled=value;$('cancel-analysis').hidden=!(value&&analysisActive);if(value&&analysisActive)$('cancel-analysis').disabled=false;$('analyze-text').textContent=value?'처리 중…':mode==='demo'?'예시 다시 분석':'네 칸 분석하기';}
function modelInfo(){return model?{name:model.name,version:model.version||null,sha256:model.sha256||null,source:model.source||null}:null;}
function currentRun(truths){return {schema_version:2,frame_id:frameId,image_sha256:imageHash,image_name:$('image-caption').dataset.filename||'sample.svg',source:mode==='demo'?'demo':'model',analyzed_at:analyzedAt,threshold:Number($('threshold').value)/100,model:modelInfo(),rois:rois.map(r=>({...r})),preprocessing:PREPROCESSING,quality:qualityChecks,analysis_duration_ms:analysisDuration,records:records(truths)};}
function refreshQualityNote(){const issues=qualityChecks.flatMap((q,i)=>q?[...q.reasons,...q.warnings].map(r=>ids[i]+': '+r.message):[]);$('quality-message').textContent=issues.join(' / ');$('quality-message').hidden=!issues.length;}
function saveSettings(){if(mode==='demo')return;try{localStorage.setItem('parking-four-settings',JSON.stringify({version:1,rois,threshold:Number($('threshold').value),default_model:'bundled'}));}catch{}}
function restoreSettings(){try{const v=JSON.parse(localStorage.getItem('parking-four-settings')||'null');if(v?.version===1){rois=validateRegions(v.rois);if(Number.isInteger(v.threshold)&&v.threshold>=50&&v.threshold<=99)$('threshold').value=v.threshold;$('threshold-value').innerHTML=$('threshold').value+'<small>%</small>';}}catch{}}
function showRegionWarnings(value){const warnings=regionWarnings(value);$('region-warning').textContent=warnings.map(w=>w.message).join(' ');$('region-warning').hidden=!warnings.length;return warnings;}

function setModelMessage(message,error=false){$('model-message').textContent=message;$('model-message').className='form-message'+(error?' error':'');}
function invalidate(message){revision++;predictions=null;results=[];qualityChecks=[];analyzedAt=null;analysisDuration=null;expanded.clear();lastRun=null;refreshQualityNote();render();if(message)toast(message);}
function classify(){if(!predictions){results=[];return;}results=predictions.map((p,i)=>qualityChecks[i]&&!qualityChecks[i].valid?{status:'uncertain',confidence:0,probabilities:{empty:null,occupied:null},prediction_skipped:true,reason:qualityChecks[i].reasons.map(r=>r.message).join(' '),quality:qualityChecks[i]}:classifyPrediction(p,Number($('threshold').value)/100,mode==='demo'?'빈자리':emptyClass,mode==='demo'?'사용 중':occupiedClass));}

function render(){const counts=results.length?summarize(results):null;for(const key of ['empty','occupied','uncertain'])$(key+'-count').textContent=counts?counts[key]:'—';$('available-slots').textContent=counts?(counts.empty?ids.filter((_,i)=>results[i].status==='empty').join(', ')+'에서 주차할 수 있어요':'현재 안내 가능한 빈자리가 없어요'):'사진과 모델을 준비해 분석해주세요';
 $('mode-pill').replaceChildren();const dot=document.createElement('span');$('mode-pill').append(dot,document.createTextNode(mode==='demo'?'예시 시연 모드':model?'AI 모델 연결됨':'사진 분석 준비'));
 $('model-state').textContent=model?'모델 연결됨':'시연 데이터';if(!model&&mode!=='demo')$('model-state').textContent='모델 연결 필요';$('model-caption').textContent=model?model.name:'실제 분석은 모델 연결 후 가능';$('connect-shortcut').textContent=model?'모델 설정 보기 ↗':'모델 연결하기 ↗';$('last-analysis').textContent=results.length?(mode==='demo'?'예시 결과':lastRun||'방금 전'):'분석 전';$('results-tag').textContent=mode==='demo'?'DEMO RESULTS':results.length?'MODEL RESULTS':'READY TO ANALYZE';$('mode-note').querySelector('p').textContent=mode==='demo'?'지금은 고정된 결과를 보여주는 예시 시연입니다. 실제 사진은 모델을 연결해 분석하세요.':model?'업로드한 사진은 이 브라우저에서만 분석합니다. 실제 주차 여부는 현장과 다를 수 있어요.':'학습한 모델을 연결한 뒤 분석하세요. 사진의 각 주차칸에 영역이 맞는지도 확인해주세요.';
 $('analyze-text').textContent=busy?'분석 중…':mode==='demo'?'예시 다시 분석':'네 칸 분석하기';renderRois();renderCards();}
function renderRois(){const layer=$('roi-layer');layer.replaceChildren();rois.forEach((r,i)=>{const b=document.createElement('button');b.className='roi '+(results[i]?.status||'pending')+(editing&&selected===i?' selected':'');Object.assign(b.style,{left:r.x*100+'%',top:r.y*100+'%',width:r.w*100+'%',height:r.h*100+'%'});b.setAttribute('aria-label',r.id+' '+(labels[results[i]?.status]||'분석 대기')+' 자세히 보기');const s=document.createElement('span');s.className='roi-label'+(r.y<.06?' roi-label-inside':'');const strong=document.createElement('b');strong.textContent=r.id;s.append(strong,document.createTextNode(labels[results[i]?.status]||'영역'));b.append(s);b.addEventListener('click',()=>{expanded.has(i)?expanded.delete(i):expanded.add(i);renderCards();$('slot-cards').children[i].scrollIntoView({behavior:'smooth',block:'nearest'});});layer.append(b);});}
function renderCards(){const root=$('slot-cards');root.replaceChildren();ids.forEach((id,i)=>{const result=results[i],status=result?.status||'pending';const card=document.createElement('article');card.className='slot-card '+status;card.innerHTML='<div class="slot-top"><div class="slot-id"><span class="parking-mark">P</span><span>'+id+'</span></div><span class="status-badge">'+labels[status]+'</span></div><div class="confidence-row"><span>최고 예측 확률</span><strong>'+(result&&!result.prediction_skipped?(result.confidence>=.999?'99.9%+':(result.confidence*100).toFixed(1)+'%'):'—')+'</strong></div><div class="confidence-track"><div style="width:'+(result?result.confidence*100:0)+'%"></div></div><button class="slot-detail" aria-expanded="'+expanded.has(i)+'">'+(expanded.has(i)?'상세 내용 접기':'잘라낸 이미지와 확률 보기')+'<span>'+(expanded.has(i)?'−':'↗')+'</span></button>';
 card.querySelector('button').onclick=()=>{expanded.has(i)?expanded.delete(i):expanded.add(i);renderCards();$('slot-cards').children[i].querySelector('button').focus();};if(expanded.has(i)){try{const canvas=cropRegion($('parking-image'),rois[i]);canvas.className='slot-crop';canvas.setAttribute('role','img');canvas.setAttribute('aria-label',id+' 잘라낸 주차칸');card.append(canvas);}catch{}const p=document.createElement('p');p.className='probability-text';p.textContent=result?.prediction_skipped?'품질 확인 필요: '+result.reason:result?'빈자리 '+(result.probabilities.empty*100).toFixed(1)+'% · 사용 중 '+(result.probabilities.occupied*100).toFixed(1)+'%'+(mode==='demo'?' (시연 값)':''):'분석 후 클래스별 확률을 확인할 수 있어요.';card.append(p);}root.append(card);});}
function download(name,data,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function records(truths=null){return results.map((r,i)=>({frame_id:frameId,slot_id:ids[i],source:mode==='demo'?'demo':'model',truth:truths?.[i]||null,...r}));}
function savedEvaluation(){return history.find(h=>h.frame_id===frameId&&sameRegions(h.rois,rois));}
function exportResults(){if(!results.length)return toast('사진을 먼저 분석해주세요.',true);const run=currentRun(savedEvaluation()?.records.map(r=>r.truth));download('parking-analysis-'+(mode==='demo'?'demo':frameId.replace(':','-'))+'.json',{...run,mode:mode==='demo'?'demo':'model',note:mode==='demo'?'고정된 시연 데이터입니다. 성능 평가에 사용하지 마세요.':null});toast('분석 결과를 JSON으로 저장했습니다.');}

async function uploadImage(file){
 if(busy||!file)return;
 const image=$('parking-image'), previousSrc=image.src;
 let next, displayTimer;
 setBusy(true);
 try {
  next=await preparePhoto(file);const nextHash=await fingerprintFile(file);
  image.src=next.url;
  await Promise.race([image.decode(),new Promise((_,reject)=>{displayTimer=setTimeout(()=>reject(new Error('사진 표시 시간이 초과됐습니다. 다시 선택해주세요.')),20000);})]);
  activePhoto?.dispose(); activePhoto=next; next=null;imageHash=nextHash;
  $('image-stage').style.aspectRatio=activePhoto.width+'/'+activePhoto.height;
  image.alt='업로드한 주차장 사진';if(mode==='demo')restoreSettings();mode='image';$('roi-confirmed').checked=false;$('photo-confirmation').hidden=false;
  $('image-caption').textContent=file.name+' · '+activePhoto.width+' × '+activePhoto.height;
  $('image-caption').dataset.filename=file.name;$('canvas-label').textContent='UPLOADED IMAGE';
  invalidate('사진을 불러왔어요. 네 칸의 영역을 확인해주세요.');return true;
 } catch(e) {
  image.src=previousSrc; next?.dispose();
  toast(e.message||'사진을 읽을 수 없습니다.',true);return false;
 } finally {clearTimeout(displayTimer);setBusy(false);}
}
async function resetSample(){if(busy)return;setEditing(false);activePhoto?.dispose();activePhoto=null;imageHash=null;qualityChecks=[];analyzedAt=null;analysisDuration=null;$('photo-confirmation').hidden=true;refreshQualityNote();mode='demo';rois=defaults();$('parking-image').src='sample.svg';$('parking-image').alt='네 개의 주차칸이 있는 고정 시연 그림';$('image-stage').style.aspectRatio='';$('image-caption').textContent='예시 이미지 · 고정된 시연 결과';delete $('image-caption').dataset.filename;$('canvas-label').textContent='SAMPLE VIEW';predictions=fixture;frameId='demo';expanded.clear();lastRun=null;revision++;classify();render();toast('예시 시연으로 전환했습니다.');}
async function analyze(){
 if(busy)return;if(editing)setEditing(false);
 if(mode==='demo'){if(!sameRegions(rois,defaults()))return toast('예시 결과는 기본 영역에만 제공됩니다. 실제 사진과 모델을 사용하거나 예시로 돌아가세요.',true);predictions=fixture;classify();render();toast('고정된 시연 결과를 불러왔습니다.');return;}
 try{rois=validateRegions(rois);}catch(e){return toast(e.message,true);}
 if(!$('roi-confirmed').checked){$('roi-confirmed').focus();return toast('사진의 A1~A4가 서로 다른 실제 주차칸에 맞는지 확인해 주세요.',true);}
 if(!model){open('model-dialog');return;}
 const startRevision=revision;cancelRequested=false;analysisActive=true;setBusy(true);const started=performance.now();
 try{await $('parking-image').decode();const next=[],checks=[];
  for(let i=0;i<4;i++){if(cancelRequested)throw new Error('분석을 취소했습니다.');$('analyze-text').textContent=ids[i]+' 분석 중…';$('analysis-progress').textContent=(i+1)+' / 4칸 분석 중';await new Promise(resolve=>requestAnimationFrame(()=>setTimeout(resolve,0)));const canvas=cropRegion($('parking-image'),rois[i]);const quality=inspectCanvas(canvas);checks.push(quality);next.push(quality.valid?await model.predict(canvas):null);}
  if(cancelRequested)throw new Error('분석을 취소했습니다.');if(startRevision!==revision)return;
  qualityChecks=checks;predictions=next;frameId='sha256:'+imageHash;analyzedAt=new Date().toISOString();lastRun=new Date(analyzedAt).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'});analysisDuration=Math.round(performance.now()-started);classify();expanded.clear();refreshQualityNote();saveSettings();render();$('analysis-progress').textContent=(analysisDuration/1000).toFixed(1)+'초 · 브라우저에서 분석 완료';toast(checks.some(q=>!q.valid)?'품질이 부족한 칸은 확인 필요로 표시했습니다.':'네 칸의 분석을 완료했습니다.');
 }catch(e){invalidate();$('analysis-progress').textContent='';toast(e.message.startsWith('분석을 취소')?e.message:'분석 실패: '+e.message,!cancelRequested);}finally{analysisActive=false;setBusy(false);}
}

function regionTable(){const root=$('roi-table');root.replaceChildren();rois.forEach(r=>{const row=document.createElement('div');row.className='roi-input-row';const b=document.createElement('strong');b.textContent=r.id;row.append(b);['x','y','w','h'].forEach((key,i)=>{const label=document.createElement('label');label.textContent=['왼쪽 X %','위쪽 Y %','너비 %','높이 %'][i];const input=document.createElement('input');Object.assign(input,{type:'number',min:key==='w'||key==='h'?.1:0,max:100,step:.1,value:Math.round(r[key]*1000)/10});input.dataset.key=key;input.setAttribute('aria-label',r.id+' '+label.textContent);label.append(input);row.append(label);});root.append(row);});}
function validRois(value){const next=validateRegions(value);showRegionWarnings(next);return next;}
function regionDialog(){regionTable();showRegionWarnings(rois);renderProfiles();open('regions-dialog');}
function setEditing(on){if(busy)return;editing=on;$('overview-nav').classList.toggle('active',!on);$('area-nav').classList.toggle('active',on);document.body.classList.toggle('editing',on);$('edit-regions').textContent=on?'✓ 영역 지정 완료':'⌗ 영역 조정';document.querySelector('.draw-selector')?.remove();if(on){const bar=document.createElement('div');bar.className='draw-selector';bar.append(document.createTextNode('지정할 칸'));ids.forEach((id,i)=>{const b=document.createElement('button');b.textContent=id;b.className=i===selected?'active':'';b.onclick=()=>{selected=i;setEditing(true);};bar.append(b);});const tip=document.createElement('span');tip.textContent='칸을 선택하고 사진 위를 드래그';bar.append(tip);$('image-stage').before(bar);$('image-stage').scrollIntoView({behavior:'smooth',block:'center'});}renderRois();}
let drag=null;const stage=$('image-stage');function point(e){const b=stage.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-b.left)/b.width)),y:Math.max(0,Math.min(1,(e.clientY-b.top)/b.height))};}stage.addEventListener('pointerdown',e=>{if(!editing||busy)return;e.preventDefault();drag=point(e);stage.setPointerCapture(e.pointerId);});stage.addEventListener('pointermove',e=>{if(!drag)return;const p=point(e),box=$('draw-box');box.hidden=false;Object.assign(box.style,{left:Math.min(p.x,drag.x)*100+'%',top:Math.min(p.y,drag.y)*100+'%',width:Math.abs(p.x-drag.x)*100+'%',height:Math.abs(p.y-drag.y)*100+'%'});});stage.addEventListener('pointerup',e=>{if(!drag)return;const p=point(e),r={id:ids[selected],x:Math.min(p.x,drag.x),y:Math.min(p.y,drag.y),w:Math.abs(p.x-drag.x),h:Math.abs(p.y-drag.y)};drag=null;$('draw-box').hidden=true;if(r.w<.02||r.h<.02){toast('영역이 너무 작아요. 주차칸 전체를 드래그해주세요.',true);return;}try{const next=rois.map((roi,i)=>i===selected?r:roi);rois=validRois(next);$('roi-confirmed').checked=false;saveSettings();invalidate(ids[selected]+' 영역을 지정했습니다.');}catch(err){toast(err.message,true);}});stage.addEventListener('pointercancel',()=>{drag=null;$('draw-box').hidden=true;});
async function connectModel(){if(busy)return;setBusy(true);setModelMessage('모델을 불러오는 중입니다. 잠시 기다려주세요.');let next;try{next=modelTab==='bundled'?await loadBundledModel():modelTab==='url'?await loadRemoteModel($('model-url').value):await loadLocalModel($('model-files').files);model?.dispose();model=next;next=null;const ec=model.classes.find(c=>/^(빈자리|empty|vacant|free|unoccupied)$/i.test(c.trim()));emptyClass=ec||model.classes[0];occupiedClass=model.classes.find(c=>c!==emptyClass);for(const id of ['empty-class','occupied-class']){$(id).replaceChildren();model.classes.forEach(c=>{const option=document.createElement('option');option.value=c;option.textContent=c;$(id).append(option);});}$('empty-class').value=emptyClass;$('occupied-class').value=occupiedClass;$('class-mapping').hidden=false;if(mode!=='demo')invalidate();else render();setModelMessage('연결됐습니다. 빈자리와 사용 중 클래스 매핑을 확인한 후 실제 사진을 업로드하세요.');}catch(e){next?.dispose();setModelMessage(e.message||'모델을 불러올 수 없습니다.',true);}finally{setBusy(false);}}
function persistHistory(){try{localStorage.setItem('parking-four-history',JSON.stringify(history));return true;}catch{toast('브라우저 저장 공간을 사용할 수 없습니다. CSV를 다운로드해주세요.',true);return false;}}
function renderEvaluation(){const verified=history.filter(r=>r.image_sha256),all=verified.flatMap(r=>r.records),correct=all.filter(r=>r.truth===r.status).length,matched=verified.filter(r=>r.records.filter(s=>s.status==='empty').length===r.records.filter(s=>s.truth==='empty').length).length,falseEmpty=all.filter(r=>r.truth==='occupied'&&r.status==='empty').length;$('eval-identity-note').textContent='중복을 확인할 수 있는 사진 '+verified.length+'장 집계 · 식별 정보가 없는 이전 기록 '+(history.length-verified.length)+'장은 목록에 보관하며 집계·CSV에서 제외합니다.';$('eval-summary').innerHTML=[['칸별 정확도',all.length?Math.round(correct/all.length*100)+'%':'—'],['빈자리 수 일치율',verified.length?Math.round(matched/verified.length*100)+'%':'—'],['사용 중 → 빈자리 오류',all.length?falseEmpty+'건':'—']].map(([label,value])=>'<div class="eval-metric"><strong>'+value+'</strong><span>'+label+'</span></div>').join('');$('truth-labels').replaceChildren();const existing=savedEvaluation();ids.forEach((id,i)=>{const label=document.createElement('label');label.textContent=id+' 실제 정답';const select=document.createElement('select');select.id='truth-'+id;[['','선택'],['empty','빈자리'],['occupied','사용 중']].forEach(([value,text])=>{const o=document.createElement('option');o.value=value;o.textContent=text;select.append(o);});select.value=existing?.records[i].truth||'';label.append(select);$('truth-labels').append(label);});const tbody=$('history-body');tbody.replaceChildren();if(!history.length){const tr=document.createElement('tr');const td=document.createElement('td');td.colSpan=4;td.textContent='아직 평가 기록이 없습니다. 실제 모델 분석 후 정답을 저장하세요.';tr.append(td);tbody.append(tr);}history.slice().reverse().forEach(run=>{const tr=document.createElement('tr'),count=run.records.filter(s=>s.status==='empty').length,truth=run.records.filter(s=>s.truth==='empty').length;[(run.date||run.frame_id)+(run.identity_quality==='legacy_unknown'?' · 이전 기록(사진 식별 미확인)':''),count+'칸',run.records.filter(s=>s.status==='uncertain').length+'칸',count===truth?'일치':'불일치 (정답 '+truth+'칸)'].forEach(text=>{const td=document.createElement('td');td.textContent=text;tr.append(td);});tbody.append(tr);});}
function saveEvaluation(){if(mode==='demo'||!model||results.length!==4)return toast('평가에는 실제 모델로 분석한 사진이 필요합니다.',true);const truths=ids.map(id=>$('truth-'+id).value);if(truths.some(t=>!t))return toast('네 칸의 정답을 모두 선택해주세요.',true);const already=history.some(h=>h.image_sha256===imageHash);const run={...currentRun(truths),saved_at:new Date().toISOString(),date:new Date().toLocaleString('ko-KR')};history=upsertEvaluation(history,run);const saved=persistHistory();renderEvaluation();if(saved)toast(already?'같은 사진의 평가 기록을 수정했습니다. 중복 집계하지 않습니다.':'정답과 분석 결과를 저장했습니다.');}
function exportEvaluation(){const verified=history.filter(r=>r.image_sha256);if(!verified.length)return toast('사진 식별 정보가 있는 새 평가 기록을 저장해주세요. 이전 기록은 목록에 보관되어 있습니다.',true);download('parking-evaluation.csv',exportEvaluationCSV(verified),'text/csv;charset=utf-8');}
function readProfiles(){try{const p=JSON.parse(localStorage.getItem('parking-four-profiles')||'{}');return p&&typeof p==='object'&&!Array.isArray(p)?p:{};}catch{return {};}}
function renderProfiles(){const select=$('profile-select');select.replaceChildren(new Option('저장된 주차장 선택',''));for(const name of Object.keys(readProfiles()).sort())select.append(new Option(name,name));}
function persistProfiles(profiles){try{localStorage.setItem('parking-four-profiles',JSON.stringify(profiles));return true;}catch{toast('설정을 저장하지 못했습니다. 영역 JSON을 다운로드해 주세요.',true);return false;}}

