$('save-profile').onclick=()=>{if(busy)return;const name=$('profile-name').value.trim();if(!name||name.length>60)return toast('주차장 이름을 1~60자로 입력해주세요.',true);try{const regions=validRois(ids.map((id,i)=>{const r={id};$('roi-table').children[i].querySelectorAll('input').forEach(input=>r[input.dataset.key]=input.value.trim()===''?NaN:Number(input.value)/100);return r;}));const profiles=readProfiles();if(!Object.hasOwn(profiles,name)&&Object.keys(profiles).length>=20)return toast('주차장 설정은 최대20개까지 저장할 수 있습니다.',true);Object.defineProperty(profiles,name,{value:{rois:regions,threshold:Number($('threshold').value)},enumerable:true,configurable:true,writable:true});if(persistProfiles(profiles)){renderProfiles();$('profile-select').value=name;toast('주차장 설정을 저장했습니다.');}}catch(e){toast(e.message,true);}};
